(()=>{
const q=s=>document.querySelector(s),escape=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const groups=[
{id:'dothraki',name:'Les Dothraki',kind:'Peuples',region:'Essos · Mer Dothrak',image:'dothraki',language:'Dothraki',figures:'Khal Drogo · Daenerys · les dosh khaleen',lead:'Un peuple de cavaliers, dont le territoire se mesure en routes et en horizons.',body:['Les Dothraki parcourent les grandes plaines d’Essos dans des communautés nomades appelées khalasars. Autour des cavaliers se déplacent les familles, les troupeaux et tout ce qui permet à une société de vivre en mouvement. Un khal commande le groupe ; khaleesi est un titre porté par son épouse.','Le cheval organise la mobilité, la richesse et une grande partie de leur imaginaire. La puissance d’un chef repose sur sa capacité à entraîner les autres et à conserver leur fidélité. Un khalasar peut se diviser lorsque son autorité disparaît : le nom d’un père ne suffit pas à assurer la succession.','Vaes Dothrak est leur centre sacré, un lieu de rencontre au pied de la Mère des Montagnes. Les dosh khaleen, veuves de khals, y occupent une place religieuse. À travers Daenerys, cette culture de la steppe entre en contact avec les cités, les langues et les ambitions du monde méditerranéen d’Essos.'],terms:['Khal : chef','Khalasar : communauté nomade','Khaleesi : titre','Vaes Dothrak : cité sacrée'],source:'https://dothraki.com/about-dothraki/'},
{id:'unsullied',name:'Les Immaculés',kind:'Armées',region:'Essos · Astapor',image:'unsullied',language:'Valyrien d’Astapor ; apprentissage de la langue commune',figures:'Ver Gris · Daenerys · Missandei',lead:'Une infanterie de formation, dont l’histoire pose la question de l’obéissance et de la liberté.',body:['Les Immaculés ne constituent pas un peuple : ce sont des soldats réduits en esclavage et formés à Astapor. Leur réputation vient d’un entraînement collectif extrêmement violent, de leur endurance et de leur capacité à tenir une ligne. La lance, le bouclier rond et le casque à pointe composent leur silhouette.','Leur efficacité repose sur la coordination. Là où une charge de cavalerie cherche le mouvement et le choc, leur force tient à la cohésion des rangs. Les villes de la baie des Serfs les vendent comme une marchandise militaire, effaçant jusqu’à leurs noms et à leur individualité.','Leur rencontre avec Daenerys change ce cadre. La liberté de rester ou de partir devient un enjeu du récit, et Ver Gris incarne progressivement une parole propre au groupe. Comprendre les Immaculés, c’est donc regarder au-delà de la discipline pour retrouver les personnes que cette institution voulait rendre interchangeables.'],terms:['Nature : infanterie','Formation : rangs serrés','Origine : Astapor','Figure : Ver Gris'],source:'https://gameofthrones.fandom.com/wiki/Unsullied'},
{id:'freefolk',name:'Le Peuple libre',kind:'Peuples',region:'Westeros · Au-delà du Mur',image:'freefolk',language:'Langue commune et ancienne langue selon les communautés',figures:'Mance Rayder · Tormund · Ygritte',lead:'Les « sauvageons » vus du Sud ; une multitude de communautés vues de l’intérieur.',body:['Le mot sauvageons vient des habitants situés au sud du Mur. Ceux qu’il désigne se nomment eux-mêmes le Peuple libre. Ils ne forment pas un royaume homogène : chasseurs de la forêt, clans de montagne et communautés du littoral entretiennent des coutumes et des rivalités différentes.','Leur liberté signifie notamment le refus d’une obéissance automatique à un seigneur héréditaire. Un roi d’au-delà du Mur doit convaincre des groupes qui n’acceptent pas tous les mêmes règles. Les Thenns, les habitants de la forêt Hantée et d’autres clans ne sont donc pas de simples variantes d’une seule armée.','Le Mur sépare des territoires, mais aussi des récits. Pour la Garde de Nuit, il faut défendre une frontière ; pour ces familles, il peut devenir l’obstacle qui les empêche d’échapper au danger. Tormund, Ygritte et Mance donnent des visages à cette tension entre la protection d’un ordre et la survie de ceux qu’il exclut.'],terms:['Nom du Sud : sauvageons','Organisation : clans','Autorité : fidélité choisie','Frontière : le Mur'],source:'https://gameofthrones.fandom.com/wiki/Free_Folk'},
{id:'nightwatch',name:'La Garde de Nuit',kind:'Ordres',region:'Westeros · Le Mur',image:'nightwatch-scene',language:'Langue commune',figures:'Jeor Mormont · Jon Snow · Samwell Tarly',lead:'Un ordre de frères jurés chargé de garder la frontière du Nord.',body:['La Garde de Nuit recrute parmi les volontaires, les bannis et les condamnés. Le serment engage une vie entière et impose de renoncer aux terres, aux titres et à la fondation d’une famille. Le noir porté par les frères matérialise ce passage hors des anciennes appartenances.','Patrouilleurs, constructeurs et intendants remplissent des missions différentes : explorer, entretenir et faire vivre les forteresses. L’ordre se veut à l’écart des querelles des couronnes, mais il dépend du reste du continent pour ses ressources et ses recrues. Sa mission se complique lorsque les dangers d’au-delà du Mur ne correspondent plus aux habitudes de ses membres.'],terms:['Siège : Châteaunoir','Engagement : à vie','Devise : veiller','Fonctions : trois corps'],source:'https://awoiaf.westeros.org/index.php/Night%27s_Watch'},
{id:'ironborn',name:'Les Fer-nés',kind:'Peuples',region:'Westeros · Îles de Fer',image:'ironborn-scene',language:'Langue commune',figures:'Balon · Yara · Theon · Euron Greyjoy',lead:'Une culture insulaire façonnée par la mer, les navires et le Dieu Noyé.',body:['La vie des Fer-nés s’organise autour d’îles pauvres en terres fertiles et ouvertes sur une mer dangereuse. Les traditions de navigation et de raid occupent une place centrale dans leur identité. Les Greyjoy dominent Pyk, mais les autres maisons des îles possèdent leurs propres capitaines et intérêts.','Le Dieu Noyé donne une dimension sacrée à cette relation à l’eau. Le prix de fer désigne une acquisition obtenue par la force, contrairement à un achat payé en or. Cette valeur proclamée ne résume pourtant pas tous les choix des personnages : Theon et Yara montrent combien une appartenance peut être vécue différemment.'],terms:['Territoire : archipel','Culte : Dieu Noyé','Force : flotte','Symbole : kraken'],source:'https://awoiaf.westeros.org/index.php/Ironborn'},
{id:'dornish',name:'Les Dorniens',kind:'Peuples',region:'Westeros · Dorne',image:'dornish-scene',language:'Langue commune, avec des influences rhoynaises',figures:'Doran · Oberyn · Ellaria · les Martell',lead:'Un Sud aux héritages mêlés, dont l’histoire ne se confond pas avec celle des autres royaumes.',body:['Dorne réunit des paysages et des communautés variés : littoraux, déserts, vallées et montagnes. L’héritage des Rhoynar, arrivés avec Nymeria, s’y est mêlé à ceux des Premiers Hommes et des Andals. Les Martell portent cette mémoire dans leurs titres et leurs traditions.','La résistance de Dorne à la conquête Targaryen a nourri une identité politique distincte. La principauté a rejoint les Sept Couronnes plus tard par une union dynastique. Les coutumes de succession et les rapports sociaux y diffèrent de ceux de nombreuses maisons du Nord et de l’Ouest.'],terms:['Siège : Lancehélion','Héritage : Rhoynar','Maison : Martell','Identité : principauté'],source:'https://awoiaf.westeros.org/index.php/Dorne'},
{id:'firstmen',name:'Les Premiers Hommes',kind:'Civilisations',region:'Westeros · Héritage ancien',image:'firstmen-scene',language:'Ancienne langue à l’origine',figures:'Lignées du Nord · récits de l’Âge des Héros',lead:'Une migration ancienne, dont la mémoire demeure surtout dans le Nord.',body:['Les Premiers Hommes appartiennent aux grandes strates historiques du continent. Leurs premiers contacts avec les Enfants de la Forêt passent par le conflit, puis par des accords que les récits ultérieurs ont transformés en mémoire fondatrice.','Leur héritage ne signifie pas qu’une population serait restée inchangée. Il subsiste dans des lignées, des coutumes et le culte des anciens dieux, tandis que les langues et les alliances ont évolué. Le Nord revendique particulièrement cette profondeur historique.'],terms:['Langue : ancienne langue','Mémoire : Âge des Héros','Culte : anciens dieux'],source:'https://awoiaf.westeros.org/index.php/First_Men'},
{id:'andals',name:'Les Andals',kind:'Civilisations',region:'Essos → Westeros',image:'andals-scene',language:'Héritage lié à la langue commune',figures:'Royaumes méridionaux · Foi des Sept',lead:'Une autre grande migration, associée aux armes, à l’écriture et aux Sept.',body:['Les Andals arrivent d’Essos dans un continent déjà occupé. Conquêtes, mariages et intégrations successives remodèlent les royaumes du Sud. Leurs traditions religieuses font de la Foi des Sept une institution majeure de Westeros.','Cette histoire explique une partie des contrastes entre le Nord et les régions méridionales. Elle ne produit pas deux blocs parfaitement séparés : les familles et les cultures se sont mêlées pendant des générations, et les identités racontées par les personnages restent aussi des constructions politiques.'],terms:['Origine : Andalos','Foi : les Sept','Héritage : royaumes du Sud'],source:'https://awoiaf.westeros.org/index.php/Andals'},
{id:'rhoynar',name:'Les Rhoynar',kind:'Civilisations',region:'Essos · Rhoyne / Westeros · Dorne',image:'rhoynar-scene',language:'Rhoynais ; puis langue commune à Dorne',figures:'Nymeria · l’héritage des Martell',lead:'La mémoire d’un peuple fluvial, transportée jusqu’au sud de Westeros.',body:['Les Rhoynar sont associés au grand fleuve Rhoyne et à ses cités. Leur affrontement avec l’expansion valyrienne conduit à une diaspora dont la migration de Nymeria vers Dorne est l’épisode le plus connu.','Leur histoire devient à Dorne une mémoire d’exil, de résistance et de fondation. La langue et certaines pratiques ont reculé ou se sont transformées, mais l’héritage rhoynais continue de distinguer la principauté dans l’ensemble des Sept Couronnes.'],terms:['Fleuve : Rhoyne','Migration : Nymeria','Héritage : Dorne'],source:'https://awoiaf.westeros.org/index.php/Rhoynar'},
{id:'valyrians',name:'Les Valyriens',kind:'Civilisations',region:'Essos · Ancienne Valyria',image:'valyrians-scene',language:'Haut valyrien et langues descendantes',figures:'Targaryen · Velaryon · anciens seigneurs dragons',lead:'Un empire disparu dont les langues, l’acier et les dragons continuent d’agir sur le monde.',body:['La puissance de Valyria s’appuyait sur les dragons et un vaste système impérial, marqué aussi par l’esclavage. Le Fléau de Valyria détruit son centre et transforme la région en territoire redouté. Sa disparition n’efface cependant ni ses héritiers ni ses techniques.','Les Targaryen conservent une part de cette tradition à Peyredragon, puis à Westeros. L’acier valyrien et le prestige de la langue ancienne montrent comment un empire peut survivre dans des objets, des usages et des revendications bien après sa chute.'],terms:['Langue : haut valyrien','Héritage : dragons','Objet : acier valyrien'],source:'https://awoiaf.westeros.org/index.php/Valyria'},
{id:'ghiscari',name:'Les Ghiscari',kind:'Civilisations',region:'Essos · Baie des Serfs',image:'ghiscari-scene',language:'Valyrien local ; ancien ghiscari dans l’histoire',figures:'Astapor · Yunkaï · Meereen',lead:'Des cités héritières de Ghis, au cœur du récit de l’esclavage et de son abolition.',body:['Les villes de la baie des Serfs gardent des traces de l’ancien monde ghiscari dans leur architecture, leurs symboles et leurs institutions. Les harpies, les pyramides et les grandes familles de maîtres composent un paysage politique différent de celui des royaumes de Westeros.','Ces cités ne sont pas interchangeables : Astapor est notamment associée à la formation des Immaculés, tandis que Meereen devient un lieu central des difficultés du gouvernement après une libération. La langue quotidienne appartient aux variétés locales du valyrien, marquées par l’histoire ghiscarie.'],terms:['Cités : trois grands centres','Symbole : harpie','Héritage : Ghis'],source:'https://gameofthrones.fandom.com/wiki/Ghiscari'},
{id:'braavosi',name:'Les Braaviens',kind:'Peuples',region:'Essos · Braavos',image:'braavos',language:'Valyrien braavien ; langue commune dans les échanges',figures:'Syrio Forel · le Seigneur de la Mer · la Banque de Fer',lead:'Une cité de canaux, de commerce et de multiples croyances.',body:['Braavos appartient aux neuf Cités libres de l’ouest d’Essos. Son récit de fondation est lié à la fuite d’esclaves de Valyria. L’accueil de populations d’origines diverses explique la diversité des temples et des traditions de cette ville maritime.','Le Titan garde son entrée ; la Banque de Fer étend son influence bien au-delà des canaux. La danse de l’eau de Syrio Forel et la Maison du Noir et du Blanc constituent d’autres portes d’entrée dans une cité dont l’identité ne se réduit pas à une seule famille régnante.'],terms:['Statut : Cité libre','Repère : Titan','Puissance : commerce'],source:'https://awoiaf.westeros.org/index.php/Braavos'},
{id:'lhazareen',name:'Les Lhazaréens',kind:'Peuples',region:'Essos · Lhazar',image:'lhazareen-scene',language:'Lhazaréen',figures:'Mirri Maz Duur',lead:'Des communautés pastorales dont le récit rappelle le coût des conquêtes.',body:['Lhazar se trouve au sud-est de la mer Dothrak. Les communautés qui y vivent sont associées à l’élevage et au culte du Grand Pâtre. Elles subissent les raids de groupes plus puissants, qui emportent des personnes réduites en esclavage.','Mirri Maz Duur donne un visage à ces populations. Son apparition déplace le regard : ce qui est raconté comme un triomphe par les conquérants peut être une catastrophe pour ceux qui en subissent le passage.'],terms:['Territoire : Lhazar','Vie : pastoralisme','Culte : Grand Pâtre'],source:'https://awoiaf.westeros.org/index.php/Lhazareen'},
{id:'faceless',name:'Les Sans-Visage',kind:'Ordres',region:'Essos · Braavos',image:'faceless-scene',language:'Plusieurs langues selon les missions',figures:'Jaqen H’ghar · Arya Stark',lead:'Un ordre religieux et un art de l’effacement de soi.',body:['Les Sans-Visage sont liés à la Maison du Noir et du Blanc et au Dieu Multiface. Ils envisagent la mort à travers une tradition qui traverse les identités, les origines et les multiples cultes du monde connu.','Leur pratique associe les arts de l’assassinat à une discipline de l’observation, du mensonge et du changement d’identité. Le parcours d’Arya pose une question centrale : peut-on renoncer à son propre nom lorsque les souvenirs et les fidélités continuent de le porter ?'],terms:['Lieu : Maison du Noir et du Blanc','Culte : Dieu Multiface','Pratique : identité'],source:'https://awoiaf.westeros.org/index.php/Faceless_Men'},
{id:'secondsons',name:'Les Puînés',kind:'Armées',region:'Essos · Compagnies de mercenaires',image:'secondsons-scene',language:'Langues des contrats et des recrues',figures:'Daario Naharis · capitaines de la compagnie',lead:'Des soldats qui vendent leur service plutôt que de servir une couronne héréditaire.',body:['Les Puînés sont une compagnie de mercenaires active en Essos. Leur organisation suit les intérêts d’un contrat et la fidélité à des capitaines, plutôt qu’une obligation féodale envers une maison.','Dans un monde où les cités achètent des forces militaires, ces compagnies peuvent changer un équilibre politique. Leur présence rappelle que les armées de Game of Thrones ne sont pas toutes les prolongements d’un peuple ou d’une dynastie.'],terms:['Nature : compagnie','Engagement : contrat','Théâtre : Essos'],source:'https://awoiaf.westeros.org/index.php/Second_Sons'},
{id:'goldencompany',name:'La Compagnie Dorée',kind:'Armées',region:'Essos · Héritage d’exilés de Westeros',image:'goldencompany-scene',language:'Langue commune et langues d’Essos',figures:'Harry Strickland dans la série',lead:'Une force de mercenaires dont la réputation est elle-même une arme.',body:['La Compagnie Dorée rassemble des soldats organisés au service de contrats. Son histoire est liée aux exilés de Westeros et, dans les livres, aux conflits dynastiques des Feunoyr.','Elle se distingue par sa réputation de discipline et de fidélité à la parole donnée. Le rôle de la compagnie et ses alliances diffèrent sensiblement entre la série et les romans : cette fiche décrit son identité générale, sans mélanger les deux intrigues.'],terms:['Nature : mercenaires','Héritage : exil','Valeur : réputation'],source:'https://awoiaf.westeros.org/index.php/Golden_Company'},
{id:'brotherhood',name:'La Fraternité sans Bannières',kind:'Ordres',region:'Westeros · Le Conflans',image:'brotherhood-scene',language:'Langue commune',figures:'Beric Dondarrion · Thoros de Myr',lead:'Un groupe né de la guerre, au contact des populations prises entre les armées.',body:['La Fraternité se développe dans les terres dévastées du Conflans. Elle se présente comme une force qui défend ceux que les grandes maisons laissent sans protection, plutôt que comme une troupe portant la bannière d’un souverain.','Ses membres ne partagent pas tous la même origine sociale. La présence de Thoros et de Beric donne aussi une place importante au culte du Maître de la Lumière. Les trajectoires de cette fraternité divergent entre l’adaptation et les romans.'],terms:['Territoire : Conflans','Enjeu : petites gens','Figures : Beric et Thoros'],source:'https://awoiaf.westeros.org/index.php/Brotherhood_without_banners'},
{id:'kingsguard',name:'La Garde Royale',kind:'Ordres',region:'Westeros · La couronne',image:'kingsguard-scene',language:'Langue commune',figures:'Barristan Selmy · Jaime Lannister · Arthur Dayne',lead:'Des chevaliers chargés de protéger le souverain, même lorsque le devoir devient un dilemme.',body:['La Garde Royale est un ordre de chevaliers reconnaissable à ses manteaux blancs. La protection du monarque et de sa famille passe avant les intérêts de naissance de ses membres.','Le serment paraît simple jusqu’au moment où la fidélité au roi entre en conflit avec d’autres obligations morales. Jaime et Barristan illustrent deux façons de vivre le poids de cette institution et le jugement qu’elle porte sur ses propres membres.'],terms:['Signe : manteau blanc','Mission : protéger','Tension : obéissance'],source:'https://awoiaf.westeros.org/index.php/Kingsguard'},
{id:'maesters',name:'Les Mestres',kind:'Ordres',region:'Westeros · La Citadelle',image:'maesters-scene',language:'Langue commune et langues étudiées',figures:'Aemon · Luwin · Pycelle · Samwell',lead:'Le savoir circule à travers ceux qui conseillent, soignent et transmettent les nouvelles.',body:['Formés à la Citadelle de Villevieille, les mestres étudient plusieurs disciplines avant de servir une forteresse ou une maison. Leur chaîne rassemble des maillons associés à des champs de connaissance.','Ils remplissent des fonctions concrètes : soins, enseignement, tenue des archives et correspondance par corbeaux. Cette place au cœur de l’information leur donne une influence qui ne ressemble ni à celle d’une armée ni à celle d’une lignée.'],terms:['Centre : Citadelle','Signe : chaîne','Réseau : corbeaux'],source:'https://awoiaf.westeros.org/index.php/Maesters'},
{id:'faithmilitant',name:'La Foi Militante',kind:'Ordres',region:'Westeros · La Foi des Sept',image:'faithmilitant-scene',language:'Langue commune',figures:'Le Grand Moineau · Lancel Lannister',lead:'Lorsque l’autorité religieuse se donne une force armée.',body:['La Foi Militante rassemble des fidèles combattants attachés au culte des Sept. Sa présence met en question la place des couronnes face à une autorité qui affirme parler au nom du sacré.','Dans la série, le retour de cette force s’accompagne de l’ascension des Moineaux. Le conflit ne concerne donc pas seulement des croyances : il touche aux privilèges, à la richesse et au pouvoir de juger les membres des grandes maisons.'],terms:['Institution : Foi des Sept','Force : fidèles armés','Enjeu : autorité'],source:'https://awoiaf.westeros.org/index.php/Faith_Militant'},
{id:'harpy',name:'Les Fils de la Harpie',kind:'Armées',region:'Essos · Meereen',image:'harpy-scene',language:'Valyrien meereenien',figures:'Un réseau clandestin de Meereen',lead:'Une résistance clandestine à la fin de l’ancien ordre esclavagiste.',body:['Les Fils de la Harpie apparaissent à Meereen après le bouleversement du pouvoir des maîtres. Dans la série, leurs masques dorés transforment des personnes anonymes en une menace collective immédiatement reconnaissable.','Le groupe agit dans les rues et dans l’ombre, plutôt que sur un champ de bataille ouvert. Son existence montre la difficulté de transformer une société : renverser ceux qui gouvernaient ne suffit pas à faire disparaître leurs réseaux et leurs intérêts.'],terms:['Signe : masque de harpie','Nature : clandestinité','Conflit : ordre social'],source:'https://awoiaf.westeros.org/index.php/Sons_of_the_Harpy'},
{id:'thenns',name:'Les Thenns',kind:'Peuples',region:'Westeros · Au-delà du Mur',image:'thenns-scene',language:'Ancienne langue et langue commune selon le contexte',figures:'Styr · Loboda dans la série',lead:'Un groupe du Peuple libre qui révèle les différences entre clans et entre adaptations.',body:['Les Thenns viennent de régions très septentrionales. Ils possèdent une identité propre à l’intérieur du vaste ensemble que les habitants du Sud appellent les sauvageons.','Leur représentation diffère fortement entre les supports. Les romans insistent sur leur organisation et le travail du bronze ; la série leur donne une image beaucoup plus menaçante. Les deux descriptions ne doivent pas être fusionnées comme s’il s’agissait d’une seule tradition uniforme.'],terms:['Ensemble : Peuple libre','Particularité : clan distinct','Lecture : série / romans'],source:'https://gameofthrones.fandom.com/wiki/Thenns'}
];
window.realmGroups=groups;const three=groups.slice(0,3);q('#peoples').className='world-peoples';q('#peoples').innerHTML=`<div class="world-intro"><p class="eyebrow">LE MONDE NE SE RÉSUME PAS AUX GRANDES MAISONS</p><h2>Ceux qui vivent<br><em>entre les frontières.</em></h2><div><p>Westeros possède des couronnes, mais Essos ne les attend pas pour exister. Des nomades, des cités marchandes, des soldats affranchis et des communautés du Nord racontent d’autres façons de vivre, de croire et d’obéir.</p><p>Un peuple, une armée et un ordre religieux ne désignent pas la même chose. Ce guide suit ces différences pour comprendre les personnages à travers les mondes auxquels ils appartiennent.</p></div><nav class="world-shortcuts"><a href="#dothraki">DOTHRAKI ↗</a><a href="#unsullied">IMMACULÉS ↗</a><a href="#freefolk">PEUPLE LIBRE ↗</a><a href="#languages">LANGUES ↗</a><a href="#houses">MAISONS ↗</a></nav></div>${three.map((g,i)=>`<article id="${g.id}" class="people-story ${i%2?'reversed':''}"><div class="people-visual"><img src="assets/${g.image}.webp" alt="Illustration : ${g.name.toLowerCase()}" loading="lazy"><div><small>${g.kind.toUpperCase()}</small><span>${g.region}</span></div></div><div class="people-reading"><p class="eyebrow">${g.region.toUpperCase()}</p><h2>${g.name}</h2><p class="story-lead">${g.lead}</p>${g.body.map(p=>`<p>${p}</p>`).join('')}<div class="people-facts"><div><small>LANGUE</small><span>${g.language}</span></div><div><small>VISAGES & REPÈRES</small><span>${g.figures}</span></div></div><div class="term-chips">${g.terms.map(t=>`<span>${t}</span>`).join('')}</div></div></article>`).join('')}<div class="peoples-library"><div class="library-title"><div><p class="eyebrow">L’INDEX DES CULTURES ET DES FORCES</p><h2>Un monde<br><em>en mouvement.</em></h2></div><p>${groups.length} fiches pour relier les territoires, les institutions et les personnages. Ouvrez une fiche pour poursuivre la lecture.</p></div><div class="library-toolbar"><label><span class="sr-only">Rechercher un peuple ou un ordre</span><input id="group-search" placeholder="Rechercher : Braavos, Garde, Valyria…"></label><div id="group-filters">${['Tout','Peuples','Armées','Ordres','Civilisations'].map((f,i)=>`<button data-category="${f}" aria-pressed="${i===0}">${f}</button>`).join('')}</div></div><p id="group-count" aria-live="polite"></p><div class="groups-grid" id="groups-grid"></div></div>`;
const imgpath=g=>`assets/${g.image}.webp`;const norm=s=>s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');let category='Tout';function renderGroups(){let term=norm(q('#group-search').value);let list=groups.filter(g=>(category==='Tout'||g.kind===category)&&norm(g.name+' '+g.lead+' '+g.region+' '+g.figures+' '+g.body.join(' ')).includes(term));q('#group-count').textContent=list.length+' fiche'+(list.length>1?'s':'')+' à explorer';q('#groups-grid').innerHTML=list.map(g=>`<button class="group-card" data-group="${g.id}"><img src="${imgpath(g)}" alt="" loading="lazy"><div><small>${g.kind.toUpperCase()} · ${g.region.split(' · ')[0]}</small><h3>${g.name}</h3><p>${g.lead}</p><span>LIRE LA FICHE ↗</span></div></button>`).join('')||'<p class="no-results">Aucun résultat. Essayez un autre nom, un territoire ou une institution.</p>';q('#groups-grid').querySelectorAll('button').forEach(b=>b.onclick=()=>openGroup(b.dataset.group))}q('#group-search').oninput=renderGroups;q('#group-filters').onclick=e=>{if(!e.target.dataset.category)return;category=e.target.dataset.category;document.querySelectorAll('[data-category]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.category===category));renderGroups()};renderGroups();function openGroup(id){const g=groups.find(g=>g.id===id);q('#archive-content').innerHTML=`<img class="archive-cover" src="${imgpath(g)}" alt="Illustration de ${g.name.toLowerCase()}"><p class="eyebrow">${g.kind.toUpperCase()} · ${g.region}</p><h2>${g.name}</h2><p class="story-lead">${g.lead}</p>${g.body.map(p=>`<p>${p}</p>`).join('')}<div class="people-facts"><div><small>LANGUE</small><span>${g.language}</span></div><div><small>FIGURES & REPÈRES</small><span>${g.figures}</span></div></div><a class="archive-source" href="${g.source}" target="_blank" rel="noopener">SOURCE & LECTURE COMPLÉMENTAIRE ↗</a>`;q('#archive-dialog').showModal();q('#archive-dialog').scrollTop=0}q('#archive-close').onclick=()=>q('#archive-dialog').close();q('#archive-dialog').addEventListener('click',e=>{if(e.target===q('#archive-dialog')){let r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
const houseData=[
['Stark','Winterfell','Le Nord','L’hiver vient.','Un loup-garou gris sur champ blanc.','Les Stark gouvernent un territoire immense, séparé du Sud par les distances et par une mémoire ancienne. Leurs liens avec les Premiers Hommes et les anciens dieux restent visibles dans le bois sacré de Winterfell. Leur conception du devoir se heurte à la politique plus mobile de la cour.','Ned · Catelyn · Robb · Sansa · Arya · Bran · Jon','north-hd'],
['Lannister','Castral Roc','Les Terres de l’Ouest','Je rugis !','Un lion d’or sur champ rouge.','Les Lannister associent une forte implantation territoriale à une influence financière et dynastique. La richesse de l’Ouest ne suffit pourtant pas à garantir la cohésion familiale : Tywin, Cersei, Jaime et Tyrion donnent des sens très différents à la fidélité au nom. « Un Lannister paie toujours ses dettes » est une formule célèbre, distincte de la devise officielle.','Tywin · Joanna · Cersei · Jaime · Tyrion','crown-hd'],
['Targaryen','Peyredragon','Héritage de Valyria','Feu et sang.','Un dragon rouge à trois têtes sur champ noir.','Héritiers de Valyria, les Targaryen ont imposé leur domination sur une grande partie de Westeros à l’aide de dragons. Leur histoire oscille entre la construction d’un pouvoir commun et les conflits de succession. Après la rébellion de Robert, l’exil transforme le nom de famille en revendication et en souvenir d’un ordre disparu.','Aerys II · Rhaella · Rhaegar · Viserys · Daenerys','dragon-hd'],
['Baratheon','Accalmie','Les Terres de l’Orage','Nôtre est la fureur.','Un cerf noir sur champ d’or.','La rébellion porte Robert au trône et place une maison des Terres de l’Orage au centre du royaume. Robert, Stannis et Renly ne partagent cependant ni la même vision du droit, ni la même manière de convaincre. Leur parenté ne les protège pas des rivalités que suscite le pouvoir.','Robert · Stannis · Renly · Shireen · Gendry','crown-hd'],
['Greyjoy','Pyk','Les Îles de Fer','Nous ne semons pas.','Un kraken d’or sur champ noir.','Les Greyjoy sont inséparables de la mer et des traditions des Fer-nés. Leur pouvoir dépend des capitaines, des flottes et d’une identité insulaire qui valorise l’indépendance. Le parcours de Theon, élevé au contact des Stark, rend particulièrement visibles les tensions entre origine, éducation et fidélité.','Balon · Yara · Theon · Euron · Aeron','wall-hd'],
['Tyrell','Hautjardin','Le Bief','Plus haut, plus fort.','Une rose d’or sur champ vert.','Le Bief apporte au royaume des terres fertiles, des réserves agricoles et une force politique considérable. Les Tyrell associent cette base matérielle à l’art des alliances. Olenna et Margaery montrent que l’influence peut se construire par les usages de la cour autant que par les armes.','Olenna · Mace · Margaery · Loras','crown-hd'],
['Martell','Lancehélion','Dorne','Insoumis, invaincus, intacts.','Un soleil rouge transpercé d’une lance d’or sur champ orange.','Les Martell gouvernent une principauté dont l’histoire avec les Targaryen diffère de celle des royaumes conquis. Leur nom conserve l’héritage de Nymeria et des Rhoynar. La retenue de Doran et l’énergie d’Oberyn expriment deux manières d’envisager la défense de la famille et de Dorne.','Doran · Oberyn · Elia · Trystane','crown-hd'],
['Tully','Vivesaigues','Le Conflans','Famille, devoir, honneur.','Une truite argentée sur un champ rouge et bleu ondé.','À travers Catelyn et Lysa, les Tully relient le Conflans au Nord et au Val. Vivesaigues occupe un espace de passage, exposé aux mouvements des armées. La devise familiale devient un ensemble d’obligations qui peuvent se soutenir ou se contredire lorsque les alliances sont mises à l’épreuve.','Hoster · Catelyn · Lysa · Edmure','north-hd'],
['Arryn','Les Eyrié','Le Val','Aussi haute qu’honneur.','Un faucon et une lune blanche sur champ bleu.','Le Val s’abrite derrière les montagnes de la Lune et les défenses des Eyrié. Jon Arryn a joué un rôle de tuteur politique et familial auprès de Robert et de Ned. Sa maison rappelle qu’un personnage absent peut laisser des liens décisifs dans toute l’histoire du royaume.','Jon Arryn · Lysa Tully · Robin Arryn','north-hd'],
['Bolton','Fort-Terreur','Le Nord','Nos lames sont acérées.','Un homme écorché rouge sur champ rose semé de gouttes.','Les Bolton représentent une autre tradition de pouvoir du Nord, associée à la crainte et à la violence. Leur emblème oppose à l’honneur proclamé par les Stark un avertissement immédiat. Les relations de Roose et Ramsay avec les autres lignées font de leur maison un enjeu important des conflits septentrionaux.','Roose · Ramsay · Walda Frey','north-hd']
];q('#houses').className='heraldry';q('#houses').innerHTML=`<div class="section-top"><span>LES GRANDES MAISONS / NOMS & ARMES</span><span>10 LIGNÉES À EXPLORER</span></div><div class="library-title"><div><p class="eyebrow">DES EMBLÈMES QUI RACONTENT UN TERRITOIRE</p><h2>Sous la<br><em>bannière.</em></h2></div><p>Un blason identifie une famille avant qu’un personnage ne prononce son nom. Choisissez une maison pour retrouver ses armes, sa devise et sa place dans le royaume.</p></div><div class="heraldry-tabs" role="tablist" aria-label="Choisir une grande maison">${houseData.map((h,i)=>`<button role="tab" aria-selected="${i===0}" aria-controls="heraldry-panel" data-heraldry="${i}"><img src="assets/sigils/${h[0].toLowerCase()}.svg" alt="" loading="lazy"><span>${h[0]}</span></button>`).join('')}</div><div class="heraldry-feature" id="heraldry-panel" role="tabpanel"></div><p class="heraldry-note">Armoiries héraldiques de référence issues de A Wiki of Ice and Fire. Les versions graphiques de la série peuvent varier. <a href="#sources">Crédits des images ↗</a></p>`;
function selectHouse(i){const h=houseData[i];q('#heraldry-panel').innerHTML=`<div class="heraldry-image"><img src="assets/sigils/${h[0].toLowerCase()}.svg" alt="Armoiries de la maison ${h[0]} : ${h[4].toLowerCase()}"><small>${h[4]}</small></div><div class="heraldry-reading"><p class="eyebrow">${h[2].toUpperCase()} · ${h[1].toUpperCase()}</p><h3>${h[0]}</h3><blockquote>« ${h[3]} »</blockquote><p>${h[5]}</p><p class="house-persons">${h[6]}</p><a href="#genealogy" class="line-button" data-tree-house="${h[0]}">EXPLORER CETTE LIGNÉE ↗</a></div>`;document.querySelectorAll('[data-heraldry]').forEach(b=>b.setAttribute('aria-selected',+b.dataset.heraldry===+i));q('[data-tree-house]').onclick=()=>document.querySelector(`[data-family="${h[0]}"]`)?.click()}q('.heraldry-tabs').onclick=e=>{let b=e.target.closest('[data-heraldry]');if(b)selectHouse(+b.dataset.heraldry)};q('.heraldry-tabs').onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();let i=+document.activeElement.dataset.heraldry;i=e.key==='Home'?0:e.key==='End'?houseData.length-1:(i+(e.key==='ArrowRight'?1:-1)+houseData.length)%houseData.length;selectHouse(i);q(`[data-heraldry="${i}"]`).focus()};selectHouse(0);
const langs=[
['common','La langue commune','WESTEROS · LES ÉCHANGES DU MONDE CONNU','Le langage partagé des Sept Couronnes.','Les régions de Westeros possèdent des accents et des usages sociaux distincts, mais la langue commune permet généralement de communiquer du Nord à Dorne. Les mestres, marchands et voyageurs la transportent aussi au-delà du détroit.','Le langage ne fait pas disparaître les différences : la manière de parler peut signaler une origine, une éducation ou une position sociale. Dans la série, elle est principalement représentée par l’anglais des dialogues.','Westeros · comptoirs et échanges d’Essos',[], 'https://awoiaf.westeros.org/index.php/Common_Tongue'],
['dothraki','Le dothraki','ESSOS · LA MER DOTHRAK','Une langue de la steppe, développée pour la série.','La langue des Dothraki accompagne leur vie nomade et leur culture du cheval. Le vocabulaire contient des titres et des notions que la traduction par « roi », « reine » ou « armée » simplifie trop vite.','David J. Peterson a développé cette langue à partir des éléments donnés par George R. R. Martin. Son travail ne se limite pas à une liste de sons : il comprend une grammaire et des usages qui permettent de construire des dialogues.','Khalasars · Vaes Dothrak',[['M’athchomaroon','Salutation exprimant le respect.'],['Khal','Chef d’un khalasar.'],['Khaleesi','Titre de l’épouse d’un khal.']], 'https://dothraki.com/about-dothraki/'],
['highvalyrian','Le haut valyrien','VALYRIA · HÉRITAGE & SAVOIR','Le prestige d’un empire dont le centre a disparu.','Le haut valyrien est lié à l’ancienne civilisation de Valyria et à des usages savants, religieux ou dynastiques. Sa connaissance peut signaler une éducation, une tradition familiale ou une ambition de pouvoir.','Pour la télévision, David J. Peterson a construit une langue développée à partir des expressions déjà présentes dans les livres. Les tournures conservées dans le monde de Game of Thrones ont parfois une portée rituelle autant que pratique.','Héritage valyrien · savants · Targaryen',[['Valar morghulis','Tout homme doit mourir.'],['Valar dohaeris','Tout homme doit servir.'],['Dracarys','Feu de dragon ; utilisé comme ordre aux dragons.']], 'https://dedalvs.com/work/game-of-thrones/game_of_thrones_master_dialogue.pdf'],
['lowvalyrian','Les valyriens d’Essos','ESSOS · CITÉS LIBRES & BAIE DES SERFS','Des langues apparentées, avec des histoires locales.','« Bas valyrien » recouvre des variétés descendantes de la langue de Valyria. Les Cités libres ne parlent pas toutes exactement de la même manière ; l’histoire et les contacts ont fait évoluer les langues.','Les variétés de la baie des Serfs ont notamment reçu une influence ghiscarie. Le valyrien d’Astapor ne doit donc pas être présenté comme une simple répétition du haut valyrien appris par les élites.','Braavos · Pentos · Astapor · Meereen',[], 'https://awoiaf.westeros.org/index.php/High_Valyrian'],
['old','L’ancienne langue','WESTEROS · PREMIERS HOMMES & GRAND NORD','Des voix plus anciennes que les royaumes actuels.','L’ancienne langue est associée aux Premiers Hommes. Elle a largement cédé la place à la langue commune dans les Sept Couronnes, mais demeure connue dans certaines communautés au-delà du Mur.','Les géants et une partie du Peuple libre en conservent des usages. Elle marque la distance historique et culturelle entre le monde que les seigneurs administrent et celui que les récits du Sud connaissent mal.','Au-delà du Mur · mémoire des Premiers Hommes',[], 'https://awoiaf.westeros.org/index.php/Old_Tongue'],
['rhoynish','Le rhoynais','ESSOS · RHOYNE / HÉRITAGE DORNIEN','La langue d’un peuple de fleuve et d’exil.','Les Rhoynar possédaient leur propre langue. La migration vers Dorne et les contacts avec les autres populations ont transformé sa place dans la vie quotidienne.','L’héritage rhoynais reste perceptible dans la culture dornienne, sans signifier que tous les Dorniens parlent encore la langue de leurs ancêtres. Il faut distinguer une langue vivante d’un héritage linguistique.','Rhoyne · mémoire de Dorne',[], 'https://awoiaf.westeros.org/index.php/Rhoynar'],
['ghiscari','L’ancien ghiscari','ESSOS · GHIS & SA MÉMOIRE','Une langue ancienne dont les traces ont survécu à la disparition.','L’ancien ghiscari appartient à l’histoire de l’empire de Ghis. Au temps de la série, il est considéré comme une langue morte, tandis que les habitants des cités de la baie des Serfs parlent des variétés locales du valyrien.','Son influence ne s’efface pas entièrement : des mots et des particularités ont été conservés dans les langues qui l’ont remplacé. Une trace linguistique peut ainsi survivre à l’ordre politique qui l’a produite.','Ghis · traces dans la baie des Serfs',[], 'https://gameofthrones.fandom.com/wiki/Old_Ghiscari'],
['qartheen','Le qarthien','ESSOS · QARTH','Une autre voix du vaste continent oriental.','Qarth possède une identité urbaine et linguistique distincte, située sur des routes commerciales qui relient plusieurs mondes. La cité ne relève ni de la culture dothraki ni de celle des Sept Couronnes.','Les informations disponibles sur sa langue sont moins développées que pour le dothraki et le haut valyrien de la télévision. Cette fiche indique sa présence dans l’univers sans inventer de grammaire ni de phrases.','Qarth · routes maritimes d’Essos',[], 'https://awoiaf.westeros.org/index.php/Languages'],
['lhazareen','Le lhazaréen','ESSOS · LHAZAR','La voix des communautés de l’est des steppes.','La langue lhazaréenne appartient aux peuples de Lhazar. Son existence rappelle qu’Essos comprend bien davantage de cultures que les seuls groupes longuement montrés à l’écran.','Comme pour d’autres langues peu documentées de l’univers, mieux vaut distinguer ce qui est attesté de ce qui reste indécrit. Aucun lexique complet n’est proposé ici.','Lhazar · communautés pastorales',[], 'https://awoiaf.westeros.org/index.php/Languages']
];q('#languages').className='languages';q('#languages').innerHTML=`<div class="section-top"><span>LES LANGUES / NOMMER LE MONDE</span><span>VOIX, HÉRITAGES & TRADUCTIONS</span></div><div class="library-title"><div><p class="eyebrow">DIRE, COMPRENDRE, APPARTENIR</p><h2>Chaque monde<br><em>a sa voix.</em></h2></div><p>La langue peut relier des peuples, marquer un exil ou cacher une intention. Explorez neuf langues et ensembles linguistiques, puis retrouvez quelques expressions attestées.</p></div><div class="language-workbench"><div class="language-list" aria-label="Choisir une langue">${langs.map((l,i)=>`<button data-language="${i}" aria-pressed="${i===0}"><small>${String(i+1).padStart(2,'0')}</small><span>${l[1]}</span><b>↗</b></button>`).join('')}</div><div id="language-reading" class="language-reading" aria-live="polite"></div></div><div class="language-more"><h3>Et plus loin encore…</h3><p>L’ithbénien, la langue des îles d’Été et les langues d’Asshaï rappellent l’étendue du monde connu. Leur mention ne donne pas, à elle seule, accès à un corpus aussi développé que celui des langues créées pour la télévision.</p><a href="https://dothraki.com/" target="_blank" rel="noopener">DÉCOUVRIR LE TRAVAIL DE DAVID J. PETERSON ↗</a></div>`;
function selectLanguage(i){const l=langs[i];q('#language-reading').innerHTML=`<p class="eyebrow">${l[2]}</p><h3>${l[1]}</h3><p class="story-lead">${l[3]}</p><p>${l[4]}</p><p>${l[5]}</p><div class="language-area"><small>OÙ LA RETROUVER</small><span>${l[6]}</span></div>${l[7].length?`<h4>QUELQUES REPÈRES</h4><div class="phrase-list">${l[7].map(p=>`<div><strong>${p[0]}</strong><p>${p[1]}</p></div>`).join('')}</div>`:'<p class="language-note">Cette fiche décrit la langue et son contexte ; elle ne propose pas de traduction inventée.</p>'}<a class="archive-source" href="${l[8]}" target="_blank" rel="noopener">SOURCE & APPROFONDISSEMENT ↗</a>`;document.querySelectorAll('[data-language]').forEach(b=>b.setAttribute('aria-pressed',+b.dataset.language===+i))}q('.language-list').onclick=e=>{let b=e.target.closest('[data-language]');if(b)selectLanguage(+b.dataset.language)};selectLanguage(0);
const faiths=[['Les anciens dieux','Bois sacrés · barrals · mémoire','Le culte des anciens dieux est lié aux arbres et aux lieux plutôt qu’à une grande hiérarchie de prêtres. Les barrals à visage sculpté forment des points de mémoire et de recueillement. Cette tradition reste particulièrement importante dans le Nord et parmi une partie du Peuple libre.','weirwood-scene'],['La Foi des Sept','Septs · septons · septas','Les Sept sont les sept aspects d’une même divinité : le Père, la Mère, le Guerrier, la Jouvencelle, le Ferrant, l’Aïeule et l’Étranger. Cette religion possède des lieux, des ministres et une autorité institutionnelle qui peuvent entrer en conflit avec les souverains.','sevenfaith-scene'],['Le Maître de la Lumière','R’hllor · feu · prêtres rouges','Le culte de R’hllor oppose la lumière et la chaleur aux ténèbres et au froid. Les prêtres rouges interprètent les flammes, les signes et les prophéties. Melisandre et Thoros n’en offrent pas une expression identique : la croyance est aussi traversée par les doutes de ceux qui la portent.','redpriest-scene'],['Le Dieu Noyé','Îles de Fer · mer · renaissance','Le Dieu Noyé est au cœur de la religion des Fer-nés. Les rites associent l’eau, l’épreuve et le retour à la vie. Cette foi donne une signification collective aux dangers de la mer et aux traditions qui structurent l’identité des îles.','drownedgod-scene'],['Le Dieu Multiface','Braavos · Maison du Noir et du Blanc','La tradition des Sans-Visage envisage la mort à travers les visages multiples que les peuples donnent au sacré. La Maison du Noir et du Blanc accueille des représentations de divinités différentes. L’effacement de l’identité personnelle y prend un sens à la fois religieux et pratique.','faceless-scene'],['Le Grand Étalon','Dothraki · ciel · cheval','Les croyances dothraki accordent au cheval une place centrale, jusque dans leur représentation du ciel et du destin. Vaes Dothrak et les dosh khaleen donnent une forme concrète à cette dimension sacrée de la vie du khalasar.','dothraki']];q('#beliefs').className='beliefs';q('#beliefs').innerHTML=`<div class="section-top"><span>LES CROYANCES / CE QUI DÉPASSE LES ROIS</span><span>6 TRADITIONS À COMPRENDRE</span></div><div class="library-title"><div><p class="eyebrow">LE SACRÉ A AUSSI UNE GÉOGRAPHIE</p><h2>Des dieux.<br><em>Des fidélités.</em></h2></div><p>Les croyances vivent dans des lieux, des gestes et des institutions. Leurs interprétations influencent les alliances autant que les consciences.</p></div><div class="belief-grid">${faiths.map(f=>`<article><img src="assets/${f[3]}.webp" alt="Évocation du territoire ou de l’élément associé à ${f[0].toLowerCase()}" loading="lazy"><div><small>${f[1]}</small><h3>${f[0]}</h3><p>${f[2]}</p></div></article>`).join('')}</div>`;
const beasts=[['Dragons','Valyria · Targaryen','dragon-hd','Les dragons rendent visible une puissance qui dépasse les défenses et les armées des hommes. Leur rôle dans la conquête Targaryen explique pourquoi leur retour change immédiatement les calculs politiques. Une force capable de renverser un ordre ne suffit pourtant pas à définir ce qui doit le remplacer.'],['Loups géants','Le Nord · Stark','wolf-hd','Plus grands que les loups ordinaires, ils sont associés au Nord et à l’emblème Stark. Leurs liens avec les enfants de Winterfell rendent l’animal inséparable de questions d’identité, d’instinct et d’appartenance.'],['Géants','Au-delà du Mur','giants-scene','Les géants du grand Nord ne sont pas de simples légendes pour les communautés qui vivent près d’eux. Leur présence montre combien le monde réel du Peuple libre diffère des récits que l’on répète au sud du Mur.'],['Marcheurs blancs & morts animés','Les terres de l’éternel hiver','wall-hd','Les Marcheurs blancs et les morts qu’ils animent ne sont pas la même chose. Les premiers appartiennent à une menace ancienne ; les seconds constituent les corps qu’elle met en mouvement. Cette distinction transforme une armée en question de survie collective.'],['Enfants de la Forêt','Avant les royaumes des hommes','childrenforest-scene','Les Enfants de la Forêt appartiennent aux plus anciennes strates de l’histoire de Westeros. Leur relation aux arbres, à la mémoire et aux premiers habitants humains fait du monde naturel un acteur du récit, plutôt qu’un simple décor.']];q('#bestiary').className='bestiary-expanded';q('#bestiary').innerHTML=`<div class="section-top"><span>LE BESTIAIRE / AUX LIMITES DES RÉCITS</span><span>CRÉATURES & ÊTRES ANCIENS</span></div><div class="library-title"><div><p class="eyebrow">LES HOMMES NE SONT PAS SEULS</p><h2>Les autres<br><em>présences.</em></h2></div><p>Certains êtres changent les frontières du possible. D’autres révèlent ce que les royaumes ont oublié de leur propre histoire.</p></div><div class="creature-list">${beasts.map((b,i)=>`<article><div class="creature-visual"><img src="assets/${b[2]}.webp" alt="Illustration : ${b[0]}" loading="lazy"><span>${String(i+1).padStart(2,'0')}</span></div><div><p class="eyebrow">${b[1].toUpperCase()}</p><h3>${b[0]}</h3><p>${b[3]}</p></div></article>`).join('')}</div>`;
const eras=[['L’Âge des Héros','Les récits de fondation','Les Premiers Hommes et les Enfants de la Forêt occupent le premier plan d’une histoire où les faits et les légendes se mêlent. Le Mur, les anciens pactes et les origines des grandes lignées font partie de cette mémoire.'],['La Conquête','La naissance du Trône de Fer','Aegon Targaryen et ses sœurs imposent leur domination à une grande partie de Westeros avec leurs dragons. Les royaumes ne rejoignent pas tous la couronne de la même manière : Dorne suit une histoire distincte.'],['La Rébellion','Les blessures d’un ordre renversé','La guerre contre Aerys II conduit Robert Baratheon au trône. Les héritiers Targaryen prennent le chemin de l’exil, tandis que les alliances de la guerre deviennent les relations personnelles et politiques du récit suivant.'],['Au début de la série','Un équilibre instable','Robert règne à Port-Réal, Ned gouverne Winterfell et les Lannister occupent une place centrale à la cour. En Essos, les destins de Daenerys et des peuples qu’elle rencontre ouvrent un autre espace de l’histoire.']];q('#history').className='world-history';q('#history').innerHTML=`<div class="section-top"><span>L’HISTOIRE / DES MONDES QUI SE SUPERPOSENT</span><span>REPÈRES SANS LES DÉNOUEMENTS</span></div><div class="library-title"><div><p class="eyebrow">AVANT LES PREMIÈRES SCÈNES</p><h2>Ce qui précède<br><em>la couronne.</em></h2></div><p>Ces repères donnent du contexte aux familles et aux territoires. Les filiations secrètes restent contrôlables dans l’arbre généalogique.</p></div><div class="eras">${eras.map((e,i)=>`<article><span>${String(i+1).padStart(2,'0')}</span><div><small>${e[1]}</small><h3>${e[0]}</h3><p>${e[2]}</p></div></article>`).join('')}</div>`;
q('#sources').className='world-sources';q('#sources').innerHTML=`<p class="eyebrow">SOURCES & IMAGES</p><h2>Pour continuer<br><em>l’exploration.</em></h2><div class="sources-grid"><div><h3>L’univers</h3><a href="https://www.hbo.com/game-of-thrones" target="_blank" rel="noopener">Game of Thrones — HBO ↗</a><a href="https://www.westeros.org/Citadel/Concordance/" target="_blank" rel="noopener">Westeros.org — The Citadel ↗</a><a href="https://awoiaf.westeros.org/" target="_blank" rel="noopener">A Wiki of Ice and Fire ↗</a><a href="https://gameofthrones.fandom.com/wiki/Game_of_Thrones" target="_blank" rel="noopener">Wiki of Westeros — adaptation télévisée ↗</a><a href="https://quartermaester.info/" target="_blank" rel="noopener">Quartermaester — repères cartographiques ↗</a></div><div><h3>Les langues</h3><a href="https://dothraki.com/" target="_blank" rel="noopener">David J. Peterson — Dothraki ↗</a><a href="https://dedalvs.com/work/game-of-thrones/game_of_thrones_master_dialogue.pdf" target="_blank" rel="noopener">Documents de dialogue — saisons 3 à 8 ↗</a><a href="https://dothraki.org/" target="_blank" rel="noopener">Communauté Dothraki & Valyrian ↗</a><p>Les formules sont transcrites en alphabet latin. Les langues peu documentées sont présentées sans lexique inventé.</p></div><div><h3>Les images</h3><p>Illustrations d’ambiance et portraits : interprétations créées pour ce guide. Les images de territoires accompagnant les fiches peuvent évoquer un contexte plutôt que représenter exactement le lieu nommé.</p><p>Les images d’armoiries sont reproduites depuis A Wiki of Ice and Fire ; les crédits, auteurs et licences sont détaillés ci-dessous.</p></div></div><details class="sigil-credits"><summary>CRÉDITS DES ARMOIRIES</summary><div id="sigil-credits-list"></div><p><a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noopener">Licence CC BY-SA 3.0 ↗</a> · Images reproduites sans modification du dessin.</p></details><p class="source-scope">Ce guide privilégie la série Game of Thrones et signale les différences importantes avec les romans. Il se concentre sur les cultures et institutions abordées dans le récit, sans prétendre recenser chaque nom de l’univers.</p>`;
fetch('assets/sigils/credits-svg.json').then(r=>r.json()).then(cs=>{q('#sigil-credits-list').innerHTML=cs.filter(c=>!c.error).map(c=>`<p><a href="${c.page}" target="_blank" rel="noopener">Maison ${c.house}</a> — ${escape(c.author||'auteur indiqué sur la page source')} · ${c.license}</p>`).join('')}).catch(()=>q('#sigil-credits-list').textContent='Consultez les pages des fichiers sur A Wiki of Ice and Fire.');
// The index remains fully visible; it does not depend on scroll-triggered visibility.
const destinations=[
['Braavos','Cité libre','Langue : valyrien braavien','Canaux, commerce, temples et Banque de Fer. Braavos est une puissance maritime dont l’histoire de fondation est liée à la fuite de l’esclavage valyrien. Le Titan annonce l’entrée dans son port, tandis que la Maison du Noir et du Blanc ouvre une autre face de la cité.','braavos','braavosi'],
['Pentos','Cité libre','Langue : valyrien pentoshi','Pentos est l’une des portes occidentales d’Essos. Sa position commerciale et ses grandes fortunes en font un lieu où les projets politiques peuvent se négocier à l’abri des regards de Westeros. Le début du parcours de Daenerys y passe par la demeure d’Illyrio Mopatis.','braavos','valyrians'],
['Volantis','Cité libre','Langue : valyrien volantain','Volantis revendique fortement l’héritage de Valyria. Ses vieilles familles et ses quartiers marquent une hiérarchie sociale profonde. Le commerce et le culte du Maître de la Lumière donnent à la cité une influence qui traverse une partie du continent.','braavos','valyrians'],
['Lys','Cité libre','Langue : valyrien lysien','Lys est une cité insulaire des mers du sud-ouest d’Essos. Elle appartient aux réseaux commerciaux des Cités libres, avec ses rivalités et ses traditions propres. Les noms des lieux d’Essos ne désignent donc pas des quartiers d’un même royaume, mais des centres politiques distincts.','braavos','valyrians'],
['Myr','Cité libre','Langue : valyrien myrien','Myr appartient au groupe des Cités libres occidentales. Elle est réputée pour certains métiers d’artisanat et de fabrication. Son nom apparaît aussi à travers des personnages qui transportent leurs savoirs et leurs croyances vers d’autres terres, comme Thoros de Myr.','braavos','brotherhood'],
['Tyrosh','Cité libre','Langue : valyrien tyroshi','Tyrosh est une puissance insulaire située sur les routes maritimes entre l’ouest d’Essos et les degrés de Pierre. Ses échanges et ses rivalités l’inscrivent dans un ensemble de cités qui s’allient et s’opposent sans relever d’une autorité commune.','braavos','secondsons'],
['Qohor','Cité libre','Langue : valyrien qohorik','Plus à l’intérieur des terres, Qohor se distingue notamment par ses traditions métallurgiques et son culte du Bouc Noir. Dans l’histoire des Immaculés, la défense de cette cité occupe une place importante dans leur réputation militaire.','unsullied','unsullied'],
['Norvos','Cité libre','Langue : valyrien norvoshi','Norvos est une cité de l’intérieur d’Essos, marquée par ses prêtres et par une vie urbaine différente de celle des grands ports. Sa présence rappelle que l’identité des Cités libres ne peut pas être réduite au commerce maritime.','braavos','valyrians'],
['Lorath','Cité libre','Langue : valyrien lorathi','Lorath complète l’ensemble des neuf Cités libres. Située sur des îles du nord-ouest d’Essos, elle rappelle l’étendue et la diversité de cette constellation politique : aucune seule cité n’en représente toutes les coutumes.','braavos','braavosi'],
['Vaes Dothrak','Cité sacrée','Langue : dothraki','Au pied de la Mère des Montagnes, Vaes Dothrak est le grand centre sacré des Dothraki. Les khalasars y convergent, et les dosh khaleen y possèdent une autorité religieuse. Le lieu constitue un point fixe dans une culture de la mobilité.','dothraki','dothraki'],
['Astapor','Baie des Serfs','Langue : valyrien astapori','Astapor est associée à la formation et à la vente des Immaculés. La cité met en évidence la façon dont un ordre économique peut transformer des personnes en instrument de puissance militaire. Son histoire devient centrale dans la rencontre entre Daenerys et les sociétés de la baie.','unsullied','unsullied'],
['Yunkaï','Baie des Serfs','Langue : valyrien local','Yunkaï est l’un des grands centres esclavagistes de la baie des Serfs. Ses maîtres, son architecture et ses stratégies ne se confondent pas avec ceux d’Astapor ou de Meereen. Les trois cités partagent un système économique, mais conservent leurs intérêts particuliers.','unsullied','ghiscari'],
['Meereen','Baie des Serfs','Langue : valyrien meereenien','Les pyramides dominent Meereen, où les rapports entre anciennes élites, personnes libérées et nouvelles autorités rendent le gouvernement particulièrement difficile. Les Fils de la Harpie sont l’une des expressions les plus visibles de cette lutte autour de l’ordre social.','unsullied','harpy'],
['Qarth','Carrefour commercial','Langue : qarthien','Qarth se situe à la jonction de grandes routes de commerce. Ses élites et ses institutions forment un monde différent des khalasars comme des Cités libres occidentales. La ville montre à Daenerys qu’un accueil peut aussi être une manière de contrôler.','braavos','valyrians'],
['Valyria','Ruines de l’ancien empire','Langue historique : haut valyrien','Le Fléau a détruit le cœur de l’ancienne puissance valyrienne. Les ruines sont devenues un lieu redouté, mais son héritage demeure ailleurs : dans les langues, l’acier, les dragons et les familles qui revendiquent encore son prestige.','dragon-hd','valyrians']
];const essos=document.createElement('div');essos.className='essos-destinations';essos.innerHTML=`<div class="library-title"><div><p class="eyebrow">LA MER ÉTROITE N’EST PAS LA FIN DU MONDE</p><h2>Au-delà<br><em>du détroit.</em></h2></div><p>Les neuf Cités libres, les cités de la baie des Serfs et les terres de l’Est : quinze destinations pour poursuivre l’exploration d’Essos.</p></div><div class="essos-tabs" aria-label="Explorer une destination d’Essos">${destinations.map((d,i)=>`<button data-destination="${i}" aria-pressed="${i===0}">${d[0]}</button>`).join('')}</div><div id="essos-reading" class="essos-reading" aria-live="polite"></div>`;q('#realm').append(essos);function destination(i){const d=destinations[i];q('#essos-reading').innerHTML=`<img src="assets/${d[4]}.webp" alt="Évocation de l’univers de ${d[0]}" loading="lazy"><div><p class="eyebrow">ESSOS · ${d[1].toUpperCase()}</p><h3>${d[0]}</h3><p>${d[3]}</p><small>${d[2]}</small><button class="line-button" data-essos-group="${d[5]}">COMPRENDRE CE MONDE ↗</button></div>`;document.querySelectorAll('[data-destination]').forEach(b=>b.setAttribute('aria-pressed',+b.dataset.destination===+i));q('[data-essos-group]').onclick=()=>openGroup(d[5])}q('.essos-tabs').onclick=e=>{if(e.target.dataset.destination)destination(+e.target.dataset.destination)};destination(0);
if(q('#genealogy'))q('#houses').after(q('#genealogy'));
})();
